@@ -1,6 +1,7 @@
 package contract_test

 import (
+	"bufio"
 	"bytes"
 	"context"
 	"errors"
@@ -9,6 +10,7 @@ import (
 	"os/exec"
 	"path/filepath"
 	"regexp"
+	"runtime"
 	"strconv"
 	"strings"
 	"syscall"
@@ -339,16 +341,146 @@ func liveMembers(t *testing.T, pgid int) []string {
 	return live
 }

-// waitGone waits for the process group to have no member (kill reports ESRCH). A group that only has
-// members that are ending can still answer EPERM or success for a moment on a loaded machine.
+// waitGone waits for the process group to have no member that can still run: kill reports ESRCH, or
+// every member is a zombie (state Z in its proc stat file). A group that only has members that are
+// ending can still answer EPERM or success for a moment on a loaded machine.
 func waitGone(t *testing.T, pgid int, what string) {
 	t.Helper()
+	if err := waitGroupGone(pgid); err != nil {
+		t.Fatalf("%s remains: %v", what, err)
+	}
+}
+
+// waitGroupGone is waitGone's wait: nil once the group is gone, else the last kill result at the deadline.
+func waitGroupGone(pgid int) error {
 	deadline := time.Now().Add(10 * time.Second)
-	for syscall.Kill(-pgid, 0) != syscall.ESRCH && time.Now().Before(deadline) {
+	for !groupGone(pgid) && time.Now().Before(deadline) {
 		time.Sleep(20 * time.Millisecond)
 	}
-	if err := syscall.Kill(-pgid, 0); err != syscall.ESRCH {
-		t.Fatalf("%s remains: %v", what, err)
+	if groupGone(pgid) {
+		return nil
+	}
+	if err := syscall.Kill(-pgid, 0); err != nil {
+		return err
+	}
+	return errors.New("a member is still running")
+}
+
+// groupGone reports whether kill finds no member of the group, or the members that remain are zombies.
+func groupGone(pgid int) bool {
+	err := syscall.Kill(-pgid, 0)
+	if err == syscall.ESRCH {
+		return true
+	}
+	if err != nil {
+		return false
+	}
+	entries, err := os.ReadDir("/proc")
+	if err != nil {
+		return false
+	}
+	for _, e := range entries {
+		if _, err := strconv.Atoi(e.Name()); err != nil {
+			continue
+		}
+		b, err := os.ReadFile("/proc/" + e.Name() + "/stat")
+		if os.IsNotExist(err) {
+			continue
+		}
+		if err != nil {
+			return false
+		}
+		s := string(b)
+		f := strings.Fields(s[strings.LastIndex(s, ")")+1:])
+		if len(f) < 3 {
+			return false
+		}
+		if f[2] == strconv.Itoa(pgid) && f[0] != "Z" {
+			return false
+		}
+	}
+	return true
+}
+
+// prctlNumber is the Linux prctl system call number by architecture; PR_SET_CHILD_SUBREAPER is 36.
+var prctlNumber = map[string]uintptr{"amd64": 157, "arm64": 167, "386": 172, "arm": 172, "riscv64": 167, "loong64": 167, "ppc64le": 171, "s390x": 172}
+
+func init() {
+	if os.Getenv("KOGEN_ZOMBIE_PARENT") != "1" {
+		return
+	}
+	syscall.RawSyscall(prctlNumber[runtime.GOARCH], 36, 1, 0)
+	child := exec.Command("sh", "-c", "exit 0")
+	child.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
+	if err := child.Start(); err != nil {
+		os.Exit(2)
+	}
+	fmt.Println(child.Process.Pid)
+	time.Sleep(time.Minute) // never waits for the child
+	os.Exit(0)
+}
+
+// TestWaitGoneCountsAZombieAsGone pins waitGone on a group whose only member has exited and is
+// kept unreaped by a parent that is a child subreaper.
+func TestWaitGoneCountsAZombieAsGone(t *testing.T) {
+	if runtime.GOOS != "linux" {
+		t.Skip("zombie state is read from /proc")
+	}
+	if _, ok := prctlNumber[runtime.GOARCH]; !ok {
+		t.Skip("no prctl number for " + runtime.GOARCH)
+	}
+	parent := exec.Command(os.Args[0])
+	parent.Env = append(os.Environ(), "KOGEN_ZOMBIE_PARENT=1")
+	out, err := parent.StdoutPipe()
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := parent.Start(); err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { parent.Process.Kill(); parent.Wait() })
+	line, err := bufio.NewReader(out).ReadString('\n')
+	pid, perr := strconv.Atoi(strings.TrimSpace(line))
+	if err != nil || perr != nil {
+		t.Fatalf("the parent reported %q: %v, %v", line, err, perr)
+	}
+	deadline := time.Now().Add(5 * time.Second)
+	for {
+		b, rerr := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
+		state := ""
+		if rerr == nil {
+			s := string(b)
+			if f := strings.Fields(s[strings.LastIndex(s, ")")+1:]); len(f) > 0 {
+				state = f[0]
+			}
+		}
+		if kerr := syscall.Kill(-pid, 0); kerr == nil && state == "Z" {
+			break
+		} else if time.Now().After(deadline) {
+			t.Fatalf("the fixture member %d is not an unreaped zombie of its group: kill %v, state %q", pid, kerr, state)
+		}
+		time.Sleep(10 * time.Millisecond)
+	}
+	start := time.Now()
+	waitGone(t, pid, "the zombie group")
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("waitGone took %v for a group of zombies", d)
+	}
+}
+
+// TestWaitGoneFailsWhileAMemberRuns pins that waitGone still fails, after its deadline, with the
+// remains message for a group whose member keeps running.
+func TestWaitGoneFailsWhileAMemberRuns(t *testing.T) {
+	sleeper := exec.Command("sleep", "60")
+	sleeper.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
+	if err := sleeper.Start(); err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { syscall.Kill(-sleeper.Process.Pid, syscall.SIGKILL); sleeper.Wait() })
+	start := time.Now()
+	err := waitGroupGone(sleeper.Process.Pid)
+	if d := time.Since(start); err == nil || d < 10*time.Second {
+		t.Fatalf("waitGone ended after %v with %v for a group with a running member", d, err)
 	}
 }

